function Init()
{
  var opts = {};
  var input = $(document.getElementById('search_input'));

  opts.select = function (event, ui)
  {
    document.getElementById('search_input').value = ui.item.value;
    document.getElementById('google_search').submit();
  }

  opts.source = function (request, response)
  {
    $.ajax(
    {
      url: 'https://www.google.com/complete/search',
      dataType: 'jsonp',
      data: {
        q: request.term,
        client: 'firefox'
      },
      success: function (data)
      {
        response($.map(data[1], function (item)
        {
          return {
            value: $("<span>").html(item).text()
          };
        }));
      }
    });
  };
    
  input.focus();
  
  GetClock();

  return input.autocomplete(opts);
}

function ShowWeather()
{
  weather = document.getElementById('weather');
  tag     = document.getElementById('weather_tag');
  img     = document.getElementById('weather_img');
  
  if(weather.style.display != 'none')
  {
    weather.style.display = 'none';
    parent.document.body.style.height = '0px';
    
    tag.src = '';
    img.src = '';
  }
  else
  {    
    weather.style.display = 'inline-block';
    parent.document.body.style.height = '880px';
    
    tag.src = 'https://old.meteo.pl/um/metco/leg_um_pl_cbase_256.png';
    img.src = 'https://old.meteo.pl/um/metco/mgram_pict.php?ntype=0u&row=466&col=232&lang=pl';
  }
}

function GetClock()
{
  var d = new Date();
  var t = Array("Niedziela","Poniedziałek","Wtorek","Środa","Czwartek","Piątek","Sobota");
  
  nhour  = d.getHours();
  nmin   = d.getMinutes();
  nsec   = d.getSeconds();
  nday   = d.getDay();
  ndate  = d.getDate();
  nmonth = d.getMonth() + 1;
  nyear  = d.getYear();
  
  if(nyear < 1000)
    nyear = nyear + 1900;

  if(nmin <= 9)
    nmin = "0" + nmin;
  
  if(nsec <= 9)
    nsec = "0" + nsec;
    
  if(ndate <= 9)
    ndate = "0" + ndate;
  
  if(nmonth <= 9)
    nmonth = "0" + nmonth;

  document.getElementById('clockbox').innerHTML = '' + t[nday] + ', ' + ndate + '.'
  + nmonth + '.' + nyear + '  ' + nhour + ':' + nmin + ':' + nsec + '&nbsp;&nbsp;';
  
  setTimeout("GetClock()", 1000);
}
